// Extract and validate image data
const item = $input.first();
const body = item.json.body;

// Support multiple input formats
let imageData;
if (body.image_url) {
  imageData = { url: body.image_url, type: 'url' };
} else if (body.image_base64) {
  imageData = { data: body.image_base64, type: 'base64' };
} else if (item.binary?.data) {
  imageData = { binary: item.binary.data, type: 'binary' };
}

const config = {
  image: imageData,
  tasks: body.tasks || ['detect', 'classify', 'ocr', 'describe'],
  output_format: body.output_format || 'json',
  confidence_threshold: body.confidence_threshold || 0.7,
  request_id: `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  timestamp: new Date().toISOString()
};

return { json: config };

