// Combine results from all vision services
const openaiResult = $input.item(0).json;
const googleResult = $input.item(1).json;
const clarifaiResult = $input.item(2).json;

// Extract OpenAI insights
const openaiAnalysis = {
  description: openaiResult.choices[0].message.content,
  provider: 'openai'
};

// Extract Google Vision results
const googleAnnotations = googleResult.responses[0];
const googleAnalysis = {
  labels: googleAnnotations.labelAnnotations?.map(l => ({
    label: l.description,
    score: l.score,
    confidence: (l.score * 100).toFixed(2) + '%'
  })) || [],
  objects: googleAnnotations.localizedObjectAnnotations?.map(o => ({
    name: o.name,
    score: o.score,
    boundingBox: o.boundingPoly
  })) || [],
  text: googleAnnotations.textAnnotations?.[0]?.description || null,
  faces: {
    count: googleAnnotations.faceAnnotations?.length || 0,
    details: googleAnnotations.faceAnnotations?.map(f => ({
      joy: f.joyLikelihood,
      sorrow: f.sorrowLikelihood,
      anger: f.angerLikelihood,
      surprise: f.surpriseLikelihood,
      confidence: f.detectionConfidence
    })) || []
  },
  safeSearch: googleAnnotations.safeSearchAnnotation,
  colors: googleAnnotations.imagePropertiesAnnotation?.dominantColors?.colors?.slice(0, 5).map(c => ({
    rgb: `rgb(${Math.round(c.color.red)}, ${Math.round(c.color.green)}, ${Math.round(c.color.blue)})`,
    score: c.score,
    pixelFraction: c.pixelFraction
  })) || [],
  provider: 'google'
};

// Extract Clarifai results
const clarifaiOutputs = clarifaiResult.outputs[0];
const clarifaiAnalysis = {
  concepts: clarifaiOutputs.data.concepts?.map(c => ({
    name: c.name,
    value: c.value,
    confidence: (c.value * 100).toFixed(2) + '%'
  })) || [],
  provider: 'clarifai'
};

// Aggregate and deduplicate labels
const allLabels = new Map();

// Add Google labels
googleAnalysis.labels.forEach(l => {
  const key = l.label.toLowerCase();
  if (!allLabels.has(key)) {
    allLabels.set(key, { label: l.label, scores: [] });
  }
  allLabels.get(key).scores.push({ provider: 'google', score: l.score });
});

// Add Clarifai concepts
clarifaiAnalysis.concepts.forEach(c => {
  const key = c.name.toLowerCase();
  if (!allLabels.has(key)) {
    allLabels.set(key, { label: c.name, scores: [] });
  }
  allLabels.get(key).scores.push({ provider: 'clarifai', score: c.value });
});

// Calculate consensus labels
const consensusLabels = Array.from(allLabels.values())
  .map(item => {
    const avgScore = item.scores.reduce((sum, s) => sum + s.score, 0) / item.scores.length;
    return {
      label: item.label,
      averageScore: avgScore,
      confidence: (avgScore * 100).toFixed(2) + '%',
      agreementCount: item.scores.length,
      providers: item.scores.map(s => s.provider)
    };
  })
  .sort((a, b) => b.averageScore - a.averageScore)
  .slice(0, 10);

// Generate summary
const summary = {
  primarySubject: consensusLabels[0]?.label || 'Unknown',
  confidence: consensusLabels[0]?.confidence || '0%',
  hasText: !!googleAnalysis.text,
  hasFaces: googleAnalysis.faces.count > 0,
  faceCount: googleAnalysis.faces.count,
  dominantColors: googleAnalysis.colors.slice(0, 3),
  safeForWork: googleAnalysis.safeSearch?.adult === 'VERY_UNLIKELY' && 
                googleAnalysis.safeSearch?.violence === 'VERY_UNLIKELY',
  contentRatings: googleAnalysis.safeSearch
};

// Compile final result
const result = {
  request_id: $input.first().json.request_id,
  timestamp: new Date().toISOString(),
  summary: summary,
  aiDescription: openaiAnalysis.description,
  consensusLabels: consensusLabels,
  detailedResults: {
    openai: openaiAnalysis,
    google: googleAnalysis,
    clarifai: clarifaiAnalysis
  },
  metadata: {
    processingTime: Date.now() - new Date($input.first().json.timestamp).getTime(),
    providersUsed: 3,
    confidenceThreshold: $input.first().json.confidence_threshold
  }
};

return { json: result };
